<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {accountRequest,currentAccount} from './client'
import {avatarUrl,type AvatarOption,type PublicAccount} from './contracts'
import Admin from './Admin.vue'
import Profile from './Profile.vue'
import '../menu/menu.css'
const copyText=ref('')
const tab=ref('users'),users=ref<(PublicAccount&{enabled:boolean})[]>([]),avatars=ref<AvatarOption[]>([]),search=ref(''),message=ref(''),busy=ref(false),loaded=ref(false)
const selected=ref<PublicAccount|null>(null),newPassword=ref(''),uploadName=ref(''),source=ref(''),file=ref<File|null>(null),fileInput=ref<HTMLInputElement>()
const filtered=computed(()=>users.value.filter(u=>`${u.username} ${u.nickname}`.toLowerCase().includes(search.value.toLowerCase())))
const errors:Record<string,string>={ACCOUNT_IN_MATCH:'该账号正在未结束的本场中，请先处理本场再修改。',PROTECTED_ACCOUNT:'管理员账号受到保护，不能在此停用或重置。',ADMIN_REQUIRED:'只有管理员可以访问此页面。',AUTH_REQUIRED:'登录已失效，请重新登录。',INVALID_MENU_COPY:'请填写1–20行文案，每行最多64个字，不含控制字符。',INVALID_ACCOUNT:'密码需8–72位，请检查输入。',INVALID_IMAGE:'请上传16–1024像素的正方形PNG、JPEG或WebP静态图片，大小不超过2MB，并填写名称与来源。',RATE_LIMITED:'操作较多，请稍后重试。'}
function error(e:unknown){message.value=errors[(e as Error).message]??'操作失败，请稍后重试。'}
async function load(){if(!currentAccount.value?.admin)return;try{users.value=(await accountRequest('users')).users;avatars.value=(await accountRequest('avatars')).avatars;copyText.value=(await accountRequest('menu-copy')).lines.join('\n');loaded.value=true}catch(e){error(e)}}
onMounted(()=>{document.title='红中痞子杠 · 管理中心';void load()})
async function toggle(u:PublicAccount&{enabled:boolean}){if(!confirm(`${u.enabled?'停用':'启用'}账号 ${u.username}？${u.enabled?'停用会撤销该账号的现有登录。':''}`))return;busy.value=true;message.value='';try{users.value=(await accountRequest('user-enabled',{id:u.id,enabled:!u.enabled})).users;message.value='账号状态已更新。'}catch(e){error(e)}finally{busy.value=false}}
async function reset(){if(!selected.value||busy.value)return;busy.value=true;message.value='';try{await accountRequest('user-password',{id:selected.value.id,password:newPassword.value});newPassword.value='';selected.value=null;message.value='密码已重置，旧登录已撤销，请将新密码告知本人。'}catch(e){error(e)}finally{busy.value=false}}
async function update(a:AvatarOption,enabled=a.enabled){busy.value=true;message.value='';try{avatars.value=(await accountRequest('avatar-update',{id:a.id,enabled,order:Number(a.order)})).avatars;message.value='头像设置已保存。'}catch(e){error(e)}finally{busy.value=false}}
async function upload(){if(!file.value||busy.value)return;if(file.value.size>2*1024*1024){error(new Error('INVALID_IMAGE'));return}busy.value=true;message.value='';try{const previewUrl=URL.createObjectURL(file.value);try{await new Promise<void>((resolve,reject)=>{const image=new Image();image.onload=()=>image.naturalWidth>=16&&image.naturalWidth<=1024&&image.naturalWidth===image.naturalHeight?resolve():reject(new Error('INVALID_IMAGE'));image.onerror=()=>reject(new Error('INVALID_IMAGE'));image.src=previewUrl})}finally{URL.revokeObjectURL(previewUrl)}const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file.value!)});await accountRequest('avatar-upload',{name:uploadName.value,source:source.value,data});await load();uploadName.value='';source.value='';file.value=null;if(fileInput.value)fileInput.value.value='';message.value='头像已上传并开放选择。'}catch(e){error(e)}finally{busy.value=false}}
async function saveCopy(){if(busy.value)return;busy.value=true;message.value='';try{const lines=copyText.value.split('\n').map(s=>s.trim()).filter(Boolean);copyText.value=(await accountRequest('menu-copy',{lines})).lines.join('\n');message.value='菜单文案已保存，下次进入主菜单时随机展示一句。'}catch(e){error(e)}finally{busy.value=false}}
function closeReset(){selected.value=null;newPassword.value=''}
</script>
<template><main class="menu-surface admin-page" data-scene="admin"><header class="menu-top"><a class="menu-link" href="?scene=menu">‹ 返回主菜单</a><span>已登录：{{currentAccount?.nickname}}</span></header><section class="menu-panel admin-panel"><h1>管理中心</h1><template v-if="!currentAccount?.admin"><p role="alert">只有管理员可以访问此页面。</p></template><template v-else><p class="muted">管理牌友账号与可选头像。已开场成员受到保护，不会因后台操作中断本场。</p><nav class="admin-tabs" aria-label="管理分类"><button :aria-pressed="tab==='users'" @click="tab='users'">用户管理</button><button :aria-pressed="tab==='avatars'" @click="tab='avatars'">头像素材</button><button :aria-pressed="tab==='copy'" @click="tab='copy'">菜单文案</button></nav><p role="status" class="menu-notice">{{message}}</p>
<div v-if="tab==='users'" class="user-layout"><section class="create-area"><Admin standalone @created="load"/></section><section class="users-area"><h2>牌友账号 <small>{{users.length}}</small></h2><label>查找用户<input v-model="search" aria-label="查找用户" placeholder="用户名或昵称"/></label><p v-if="!loaded" class="muted">正在读取账号…</p><ul class="user-list"><li v-for="u in filtered" :key="u.id"><div class="user-info"><img :src="avatarUrl(u.avatar)" alt=""/><div><strong>{{u.nickname}}</strong><span>{{u.username}} · {{u.admin?'管理员':u.enabled?'已启用':'已停用'}}</span></div></div><div v-if="!u.admin" class="user-actions"><button :disabled="busy" @click="toggle(u)">{{u.enabled?'停用':'启用'}}</button><button :disabled="busy" @click="selected=u;newPassword=''">重置密码</button></div></li></ul><p v-if="loaded&&!filtered.length" class="muted">未找到匹配账号。</p></section></div>
<form v-else-if="tab==='copy'" class="copy-editor" @submit.prevent="saveCopy"><h2>主菜单随机文案</h2><p class="muted">每行一句，1–20句，每句最多64个字。每次进入菜单随机取一句，刷新可能重复；保存后供所有登录用户使用。</p><label>文案列表<textarea v-model="copyText" aria-label="菜单文案列表" rows="8" required/></label><button class="gold-button" :disabled="busy">保存菜单文案</button></form><div v-else><form class="upload-area" @submit.prevent="upload"><h2>添加头像</h2><p class="muted">正方形PNG／JPEG／WebP，16–1024像素、最大2MB。仅开放头像选择，不改变牌桌。</p><div class="upload-fields"><label>头像名称<input v-model="uploadName" aria-label="头像名称" maxlength="32" required/></label><label>素材来源／授权备注<input v-model="source" aria-label="素材来源" maxlength="200" required/></label></div><label>选择图片<input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp" aria-label="选择头像文件" required @change="file=($event.target as HTMLInputElement).files?.[0]??null"/></label><button class="gold-button" :disabled="busy||!file">上传头像</button></form><p class="muted">顺序数字越小越靠前。停用仅阻止新选择，已有使用者仍可正常显示；保留文件，不提供删除。</p><ul class="avatar-catalog"><li v-for="a in avatars" :key="a.id"><img :src="avatarUrl(a.id)" :alt="a.name"/><strong>{{a.name}}</strong><span class="muted">{{a.enabled?'已开放':'已停用'}}{{a.builtin?' · 内置':''}}</span><p>{{a.source}}</p><label>顺序<input v-model.number="a.order" type="number" min="0" max="10000" :aria-label="`头像顺序 ${a.name}`"/></label><div class="menu-actions"><button :disabled="busy" @click="update(a,!a.enabled)">{{a.enabled?'停用头像':'启用头像'}}</button><button :disabled="busy" @click="update(a)">保存顺序</button></div></li></ul></div><Profile/></template></section><div v-if="selected" class="menu-modal" @click.self="closeReset" @keydown.esc="closeReset"><form class="menu-panel" role="dialog" aria-modal="true" aria-label="重置用户密码" @submit.prevent="reset"><h2>重置 {{selected.username}} 的密码</h2><p class="muted">保存后旧密码和原登录会话失效；未结束本场的成员不能重置。</p><label>新密码<input v-model="newPassword" aria-label="重置的新密码" type="password" autocomplete="new-password" minlength="8" maxlength="72" required/></label><div class="menu-actions"><button class="gold-button" :disabled="busy">确认重置</button><button type="button" @click="closeReset">取消重置</button></div><p role="alert">{{message}}</p></form></div></main></template>
<style scoped>
.admin-panel{width:min(100%,1200px)}.admin-tabs{display:flex;gap:12px;margin:20px 0}.user-layout{display:grid;grid-template-columns:minmax(260px,340px) minmax(0,1fr);gap:28px}.create-area{min-width:0}.users-area{min-width:0}.users-area small{color:#c3c9af;font-size:14px}.user-list{list-style:none;margin:18px 0;padding:0}.user-list li{display:flex;gap:12px;flex-wrap:wrap;align-items:center;justify-content:space-between;padding:16px 0;border-bottom:1px solid #c7ad6433}.user-info{display:flex;gap:12px;align-items:center;min-width:0}.user-info img{width:48px;height:48px;object-fit:cover;border-radius:50%;border:1px solid #dfc582}.user-info strong{display:block;font-size:16px;overflow-wrap:anywhere}.user-info span{display:block;font-size:12px;color:#bfcdb8;margin-top:6px;overflow-wrap:anywhere}.user-actions{display:flex;gap:8px}.user-actions button{font-size:13px;padding:8px 12px}.upload-fields{display:grid;grid-template-columns:1fr 1fr;gap:20px}.upload-area{padding:20px;background:#061c1788;border:1px solid #bfa26966;border-radius:12px}.avatar-catalog{list-style:none;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;padding:0;margin:24px 0}.avatar-catalog>li{padding:18px;border:1px solid #c3a15e66;border-radius:12px;background:#081f1bcc;min-width:0}.avatar-catalog>li>img{width:80px;height:80px;object-fit:cover;border:2px solid #cfb36b;border-radius:12px;display:block;margin-bottom:12px}.avatar-catalog strong,.avatar-catalog span{display:block;overflow-wrap:anywhere}.avatar-catalog p{font-size:12px;color:#b8c8b0;overflow-wrap:anywhere}.avatar-catalog .menu-actions{gap:8px}.avatar-catalog button{font-size:12px;padding:8px 10px}@media(max-width:850px){.user-layout{grid-template-columns:1fr}.avatar-catalog{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:500px){.upload-fields,.avatar-catalog{grid-template-columns:1fr}.admin-tabs button{flex:1}.user-actions{width:100%;justify-content:flex-end}}
</style>

<style scoped>
.copy-editor textarea{display:block;width:100%;box-sizing:border-box;font:inherit;line-height:1.8;resize:vertical;padding:12px;color:#fff4d5;background:#061d18;border:1px solid #819b72;border-radius:8px;margin-top:8px}.admin-tabs{flex-wrap:wrap}.copy-editor textarea:focus-visible{outline:3px solid #ffe3a2;outline-offset:3px}
</style>
